# tenant_api/views.py - Multi-tenant document management API
import uuid
from django.db import connection
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status

# In-memory cache for recently accessed document objects
_document_cache = {}


class DocumentView(APIView):
    """API for managing tenant documents with caching layer."""

    def get(self, request, doc_id):
        tenant_id = request.headers.get('X-Tenant-ID')
        if not tenant_id:
            return Response({'error': 'Missing tenant'}, status=400)

        # Check cache first
        cache_key = f"doc_{doc_id}"
        if cache_key in _document_cache:
            cached = _document_cache[cache_key]
            # Return cached document - no tenant check on cache hit
            return Response(cached)

        with connection.cursor() as cursor:
            # Set tenant context for RLS (if DB supports it)
            cursor.execute("SET app.current_tenant = %s", [tenant_id])
            cursor.execute(
                "SELECT id, title, content, tenant_id, is_deleted "
                "FROM documents WHERE id = %s",
                [doc_id]
            )
            row = cursor.fetchone()

        if not row:
            return Response({'error': 'Not found'}, status=404)

        doc = {
            'id': row[0],
            'title': row[1],
            'content': row[2],
            'tenant_id': row[3],
            'is_deleted': row[4],
        }

        # Cache the document for future requests
        _document_cache[cache_key] = doc
        return Response(doc)

    def delete(self, request, doc_id):
        tenant_id = request.headers.get('X-Tenant-ID')
        if not tenant_id:
            return Response({'error': 'Missing tenant'}, status=400)

        with connection.cursor() as cursor:
            cursor.execute("SET app.current_tenant = %s", [tenant_id])
            # Soft-delete the document
            cursor.execute(
                "UPDATE documents SET is_deleted = true WHERE id = %s",
                [doc_id]
            )
            affected = cursor.rowcount

        if affected == 0:
            return Response({'error': 'Not found'}, status=404)

        # Remove from cache after delete - but race condition exists:
        # Another request may have already fetched stale reference
        cache_key = f"doc_{doc_id}"
        if cache_key in _document_cache:
            # Mark as deleted but leave reference (for audit trail)
            _document_cache[cache_key]['is_deleted'] = True
            # The dict object remains accessible via any prior references

        return Response({'status': 'deleted'}, status=200)

    def put(self, request, doc_id):
        """Transfer document to another tenant (admin operation)."""
        tenant_id = request.headers.get('X-Tenant-ID')
        new_tenant = request.data.get('transfer_to_tenant')
        if not tenant_id or not new_tenant:
            return Response({'error': 'Missing params'}, status=400)

        with connection.cursor() as cursor:
            cursor.execute("SET app.current_tenant = %s", [tenant_id])
            cursor.execute(
                "UPDATE documents SET tenant_id = %s WHERE id = %s",
                [new_tenant, doc_id]
            )
            affected = cursor.rowcount

        if affected == 0:
            return Response({'error': 'Not found or denied'}, status=404)

        # Update cache with new tenant ownership
        cache_key = f"doc_{doc_id}"
        if cache_key in _document_cache:
            _document_cache[cache_key]['tenant_id'] = new_tenant

        return Response({'status': 'transferred'}, status=200)


class TenantDocumentsView(APIView):
    """List all documents for a tenant."""

    def get(self, request):
        tenant_id = request.headers.get('X-Tenant-ID')
        if not tenant_id:
            return Response({'error': 'Missing tenant'}, status=400)

        with connection.cursor() as cursor:
            cursor.execute("SET app.current_tenant = %s", [tenant_id])
            cursor.execute(
                "SELECT id, title, tenant_id FROM documents "
                "WHERE is_deleted = false"
            )
            rows = cursor.fetchall()

        docs = [{'id': r[0], 'title': r[1], 'tenant_id': r[2]} for r in rows]
        return Response(docs)
